import React, { useState } from 'react';
import './Sidebar.css';

const agentNames = [
  "Pre-Migration Insights Agents",
  "Data Ingestion, Pre-Check & ETL Pipeline Agents",
  "Migration Execution & Oversight Agents",
  "Post-Migration Verification & Management Agents",
  "Cross-Cutting & Support Agents"
];

function Sidebar({ onAgentClick }) {
  const [activeItem, setActiveItem] = useState(null);

  const handleClick = (name) => {
    setActiveItem(name);
    onAgentClick(name);
  };

  return (
    <aside className="sidebar">
      <div className="logo-section">
        <div className="logo-circle"></div>
        <div className="logo-text">Logo</div>
      </div>
      <nav className="nav">
        <ul>
          {agentNames.map((name) => (
            <li 
              key={name} 
              className={activeItem === name ? 'active' : ''}
              onClick={() => handleClick(name)}
            >
              <span>{name}</span>
              {activeItem === name && (
                <>
                  <div className="top-connector"></div>
                  <div className="bottom-connector"></div>
                </>
              )}
            </li>
          ))}
        </ul>
      </nav>
    </aside>
  );
}

export default Sidebar;
